  ('w:龜船', '龜船', '龟船', 'guī chuán', '"turtle ship", armored warship used by Koreans in fighting the Japanese during the Imjin war of 1592-1598 壬辰倭亂|壬辰倭乱[ren2 chen2 wo1 luan4]', '龜船', 'other', NULL),
  ('w:龜苓膏', '龜苓膏', '龟苓膏', 'guī líng gāo', 'turtle jelly, medicine made with powdered turtle shell and herbs; a similar product made without turtle shell and consumed as a dessert', '龜苓膏', 'other', NULL),
  ('w:龜茲', '龜茲', '龟兹', 'Qiū cí', 'Kucha, ancient Silk Road kingdom and Buddhist center on the northern rim of the Taklamakan Desert (Han-Tang period), in present-day Aksu, Xinjiang', '龜茲', 'other', NULL),
  ('w:龜裂', '龜裂', '龟裂', 'jūn liè', 'to crack; cracked; fissured; creviced', '龜裂', 'verb', NULL),
